builder.Services
    .AddGraphQLServer()
    .AddErrorFilter<ErrorLoggingFilter>()
    .AddDiagnosticEventListener<LoggingEventListener>();

public class ErrorLoggingFilter : IErrorFilter
{
    private readonly ILogger<ErrorLoggingFilter> _logger;

    public ErrorLoggingFilter(ILogger<ErrorLoggingFilter> logger)
    {
        _logger = logger;
    }

    public IError OnError(IError error)
    {
        _logger.LogError(
            "GraphQL Error: {Message} | Path: {Path} | Code: {Code}",
            error.Message,
            error.Path,
            error.Code);

        return error;
    }
}

public class EnrichedErrorFilter : IErrorFilter
{
    private readonly IHttpContextAccessor _httpContextAccessor;
    private readonly ILogger<EnrichedErrorFilter> _logger;

    public EnrichedErrorFilter(
        IHttpContextAccessor httpContextAccessor,
        ILogger<EnrichedErrorFilter> logger)
    {
        _httpContextAccessor = httpContextAccessor;
        _logger = logger;
    }

    public IError OnError(IError error)
    {
        var httpContext = _httpContextAccessor.HttpContext;
        var userId = httpContext?.User?.FindFirst("sub")?.Value;
        var requestId = httpContext?.TraceIdentifier;

        _logger.LogError(
            "GraphQL Error: {Message} | UserId: {UserId} | RequestId: {RequestId} | Path: {Path}",
            error.Message,
            userId,
            requestId,
            error.Path);

        return error;
    }
}

public class TelemetryErrorFilter : IErrorFilter
{
    private readonly TelemetryClient _telemetryClient;

    public TelemetryErrorFilter(TelemetryClient telemetryClient)
    {
        _telemetryClient = telemetryClient;
    }

    public IError OnError(IError error)
    {
        var properties = new Dictionary<string, string>
        {
            ["Error.Message"] = error.Message,
            ["Error.Code"] = error.Code ?? "UNKNOWN",
            ["Error.Path"] = string.Join(".", error.Path ?? Array.Empty<object>())
        };

        _telemetryClient.TrackEvent("GraphQL Error", properties);
        return error;
    }
}
